def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 5/8/0 motif is stamped at each isolated 1; the central 5 maps to 1.
    motif = [(-1, 0, 5), (-1, 1, 5), (0, -1, 8), (0, 0, 5), (0, 1, 8), (1, -1, 8), (1, 0, 5), (1, 1, 0)]
    targets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for r, c in targets:
        for dr, dc, color in motif:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out

